//! The embedded sound table, generated by `build.rs` from `app/assets/sounds/`.

include!(concat!(env!("OUT_DIR"), "/sounds.rs"));

/// One embedded sound, by its index in the name-sorted table.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SoundId(pub(crate) u16);

/// The volume group a sound plays in, from its name: `voice.` and `ui.announcer.` are voices,
/// `ambient.` is ambience, everything else is effects.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Bus {
    /// Weapons, movement, buildings, interface cues.
    Effects,
    /// Unit voices and the announcer.
    Voice,
    /// Ambience beds.
    Ambient,
}

impl SoundId {
    /// The sound with this file name (without `.ogg`).
    pub fn from_name(name: &str) -> Option<SoundId> {
        SOUND_FILES
            .binary_search_by(|(n, _)| n.cmp(&name))
            .ok()
            .map(|i| SoundId(i as u16))
    }

    /// Every embedded sound, in name order.
    pub fn all() -> impl Iterator<Item = SoundId> {
        (0..SOUND_FILES.len()).map(|i| SoundId(i as u16))
    }

    /// The number of embedded sounds.
    pub fn count() -> usize {
        SOUND_FILES.len()
    }

    /// The sounds of one family: `base` itself and its variations `base.1`, `base.2` …
    pub fn variants(base: &str) -> Vec<SoundId> {
        SoundId::all()
            .filter(|id| family_of(id.name()) == base)
            .collect()
    }

    /// The file name without `.ogg`.
    pub fn name(self) -> &'static str {
        SOUND_FILES[self.0 as usize].0
    }

    /// The embedded Ogg Vorbis bytes.
    pub fn bytes(self) -> &'static [u8] {
        SOUND_FILES[self.0 as usize].1
    }

    /// The name without a trailing variation number: `act.anvil.2` → `act.anvil`.
    pub fn family(self) -> &'static str {
        family_of(self.name())
    }

    /// The volume group of this sound.
    pub fn bus(self) -> Bus {
        let name = self.name();
        if name.starts_with("voice.") || name.starts_with("ui.announcer.") {
            Bus::Voice
        } else if name.starts_with("ambient.") {
            Bus::Ambient
        } else {
            Bus::Effects
        }
    }

    /// The index in the table.
    pub fn index(self) -> usize {
        self.0 as usize
    }
}

/// `name` without a final `.<digits>` part.
pub(crate) fn family_of(name: &str) -> &str {
    match name.rsplit_once('.') {
        Some((base, last)) if !last.is_empty() && last.bytes().all(|b| b.is_ascii_digit()) => base,
        _ => name,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn families_drop_only_a_number() {
        assert_eq!(family_of("act.anvil.2"), "act.anvil");
        assert_eq!(
            family_of("unit.corvette.fire_slot1.2"),
            "unit.corvette.fire_slot1"
        );
        assert_eq!(family_of("voice.knight.select"), "voice.knight.select");
    }

    #[test]
    fn names_are_sorted_unique_and_found() {
        assert!(SOUND_FILES.windows(2).all(|w| w[0].0 < w[1].0));
        for id in SoundId::all() {
            assert_eq!(SoundId::from_name(id.name()), Some(id));
        }
        assert_eq!(SoundId::from_name("no.such.sound"), None);
    }
}
